/**
 * Validates style definitions against the shared `definition.json` schema.
 *
 * The runtime implementation lives in `StyleSchemaValidator.js`, generated by
 * `scripts/compile-schema.mjs` from `@dicebear/schema` via @exodus/schemasafe.
 */
export class StyleSchemaValidator {
  /**
   * Validates the given data and throws `StyleValidationError` on failure.
   */
  static validate(data: unknown): void;
}
